struct nglListNode;
struct Pair { nglListNode *first; unsigned int second; };

class nglTransCompare {
public:
    bool operator()(const Pair &a, const Pair &b) {
        if ((float &)a.second > (float &)b.second)
            return true;
        if ((float &)a.second < (float &)b.second)
            return false;
        return (unsigned int)a.first < (unsigned int)b.first;
    }
};

extern "C" void make_heap_impl(Pair *, Pair *, nglTransCompare, Pair *, int *) __asm__("__make_heap__H4ZPt4pair2ZP11nglListNodeZUiZ15nglTransCompareZt4pair2ZP11nglListNodeZUiZi_X01X01X11PX21PX31_v");
extern "C" void adjust_heap_impl(Pair *, int, int, Pair, nglTransCompare) __asm__("__adjust_heap__H4ZPt4pair2ZP11nglListNodeZUiZiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X11X11X21X31_v");
extern "C" void sort_heap_impl(Pair *, Pair *, nglTransCompare) __asm__("sort_heap__H2ZPt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X01X11_v");

inline void pop_heap_impl(Pair *first, Pair *last, Pair *result, Pair value, nglTransCompare comp, int *)
{
    *result = *first;
    adjust_heap_impl(first, 0, last - first, value, comp);
}

extern "C" void partial_sort_impl(Pair *, Pair *, Pair *, Pair *, Pair *, nglTransCompare) __asm__("__partial_sort__H3ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X01X01PX11X21_v");
void partial_sort_impl(Pair *first, Pair *middle, Pair *last, Pair *, Pair *, nglTransCompare comp)
{
    make_heap_impl(first, middle, comp, (Pair *)0, (int *)0);
    for (Pair *i = middle; i < last; ++i)
        if (comp(*i, *first))
            pop_heap_impl(first, middle, i, Pair(*i), comp, (int *)0);
    sort_heap_impl(first, middle, comp);
}
